-- Schema of the old account database (a-stock-agent-skills 0.1.43) as it stands in production; no rows.
CREATE TABLE analysis_results ( code TEXT, date TEXT, result TEXT, created_at TEXT, name TEXT, score INTEGER, flags TEXT, score_breakdown TEXT, data_date TEXT, return_pct REAL, holding_days INT, framework TEXT, quote_price REAL, quote_as_of TEXT, quote_source TEXT, scoring_status TEXT DEFAULT 'complete', decision_json TEXT, PRIMARY KEY (code, date) );
CREATE TABLE holding_alerts ( id INTEGER PRIMARY KEY AUTOINCREMENT, holding_id INTEGER NOT NULL, code TEXT NOT NULL, level TEXT NOT NULL, category TEXT NOT NULL, reason_code TEXT NOT NULL, reason TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'active', evidence TEXT, opened_at TEXT NOT NULL, review_due TEXT, resolved_at TEXT, resolution_evidence TEXT, updated_at TEXT NOT NULL, CHECK (level IN ('yellow', 'red')), CHECK (category IN ('holding_deterioration', 'entry_valuation', 'unverified')), CHECK (status IN ('active', 'pending', 'resolved')) );
CREATE TABLE holding_events ( id INTEGER PRIMARY KEY AUTOINCREMENT, holding_id INTEGER NOT NULL, code TEXT NOT NULL, event_type TEXT NOT NULL, event_date TEXT NOT NULL, shares INTEGER, price REAL, fees REAL NOT NULL DEFAULT 0, tax REAL NOT NULL DEFAULT 0, cash_amount REAL, realized_pnl REAL, notes TEXT, inferred INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL, report_id INTEGER, CHECK (event_type IN ('buy', 'sell', 'dividend', 'adjustment')) );
CREATE TABLE holding_l3_conditions ( id INTEGER PRIMARY KEY AUTOINCREMENT, holding_id INTEGER NOT NULL, condition_text TEXT NOT NULL, origin_type TEXT NOT NULL DEFAULT 'original', status TEXT NOT NULL DEFAULT 'pending', evidence TEXT, as_of TEXT, next_review_date TEXT, temporary_exit_rule TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, thesis_version_id INTEGER, is_active INTEGER NOT NULL DEFAULT 1 CHECK(is_active IN (0,1)), retired_at TEXT, retired_reason TEXT, condition_scope TEXT NOT NULL DEFAULT 'legacy_unclassified' CHECK(condition_scope IN ('aggregate','core_driver','non_core','governance','legacy_unclassified')), action_level TEXT NOT NULL DEFAULT 'legacy_unclassified' CHECK(action_level IN ('review','reduce','exit','legacy_unclassified')), materiality_basis TEXT, evidence_cadence TEXT NOT NULL DEFAULT 'unspecified' CHECK(evidence_cadence IN ('quarterly','semiannual','annual','event','unspecified')), CHECK (origin_type IN ('original', 'recovered', 'new_monitoring')), CHECK (status IN ('pending', 'not_triggered', 'watch', 'triggered')) );
CREATE TABLE holding_thesis_versions ( id INTEGER PRIMARY KEY AUTOINCREMENT, holding_id INTEGER NOT NULL, version INTEGER NOT NULL, l1 TEXT NOT NULL, l2 TEXT NOT NULL, rewrite_reason TEXT NOT NULL, status TEXT NOT NULL, created_at TEXT NOT NULL, UNIQUE (holding_id, version), CHECK (status IN ('active', 'superseded')) );
CREATE TABLE holding_tier_state ( holding_id INTEGER PRIMARY KEY, tier1_status TEXT NOT NULL DEFAULT 'pending', tier2_status TEXT NOT NULL DEFAULT 'pending', tier3_status TEXT NOT NULL DEFAULT 'pending', exit_path TEXT, exit_target_pct REAL, exemption_framework TEXT, exemption_declared_at TEXT, peg_method TEXT, updated_at TEXT NOT NULL, CHECK (tier1_status IN ('pending', 'completed', 'exempted')), CHECK (tier2_status IN ('pending', 'completed')), CHECK (tier3_status IN ('pending', 'completed')) );
CREATE TABLE "holdings" ( id INTEGER PRIMARY KEY AUTOINCREMENT, code TEXT NOT NULL, name TEXT, cost_price REAL, shares INTEGER, buy_date TEXT, buy_score INTEGER, stop_loss_15 REAL, stop_loss_20 REAL, notes TEXT, updated_at TEXT, exit_price REAL, exit_date TEXT , framework TEXT, initial_shares INTEGER, main_entry_date TEXT, main_entry_basis REAL, additions_since_main REAL NOT NULL DEFAULT 0, reference_cost REAL, framework_confident INTEGER NOT NULL DEFAULT 0);
CREATE TABLE market_indicator_snapshots ( indicator_key TEXT PRIMARY KEY, value REAL NOT NULL, as_of TEXT NOT NULL, fetched_at TEXT NOT NULL, source TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'ok' );
CREATE TABLE qualitative_only_securities ( code TEXT PRIMARY KEY, name TEXT NOT NULL, industry TEXT NOT NULL, updated_at TEXT NOT NULL );
CREATE TABLE quote_snapshots ( id INTEGER PRIMARY KEY AUTOINCREMENT, code TEXT NOT NULL, price REAL NOT NULL, quote_date TEXT NOT NULL, quote_time TEXT NOT NULL, fetched_at TEXT NOT NULL, source TEXT NOT NULL, verification_sources TEXT NOT NULL, degraded INTEGER NOT NULL DEFAULT 0, valid INTEGER NOT NULL DEFAULT 1 );
CREATE TABLE retro_notes ( id INTEGER PRIMARY KEY AUTOINCREMENT, holding_id INTEGER NOT NULL, code TEXT NOT NULL, name TEXT, framework TEXT, buy_date TEXT, exit_date TEXT, buy_score INTEGER, actual_return_pct REAL, holding_days INTEGER, error_tags TEXT, thesis_notes TEXT, retro_text TEXT, framework_gap TEXT, created_at TEXT NOT NULL );
CREATE TABLE schema_migrations ( migration_id TEXT PRIMARY KEY, applied_at TEXT NOT NULL );
CREATE TABLE stock_fundamentals ( code TEXT PRIMARY KEY, name TEXT, industry TEXT, data JSON, updated_at TEXT, ttl_hours INTEGER DEFAULT 24 );
CREATE UNIQUE INDEX idx_alert_active_reason ON holding_alerts(holding_id, reason_code) WHERE status != 'resolved';
CREATE INDEX idx_alert_code_status ON holding_alerts(code, status);
CREATE INDEX idx_analysis_results_code_created ON analysis_results(code, created_at DESC);
CREATE INDEX idx_analysis_results_date ON analysis_results(date);
CREATE INDEX idx_holding_events_holding_date ON holding_events(holding_id, event_date, id);
CREATE INDEX idx_holdings_code ON holdings(code);
CREATE INDEX idx_holdings_exit ON holdings(exit_date);
CREATE INDEX idx_l3_holding_status ON holding_l3_conditions(holding_id, status);
CREATE INDEX idx_quote_snapshots_code_id ON quote_snapshots(code, id DESC);
CREATE INDEX idx_quote_snapshots_code_time ON quote_snapshots(code, fetched_at DESC);
CREATE INDEX idx_retro_framework ON retro_notes(framework);
CREATE INDEX idx_retro_holding ON retro_notes(holding_id);
CREATE INDEX idx_thesis_holding_version ON holding_thesis_versions(holding_id, version);
CREATE UNIQUE INDEX idx_thesis_one_active_per_holding ON holding_thesis_versions(holding_id) WHERE status='active';
